  }


  /** helper function to check Dock_Qualifier_dispatch_coordinator_process_dock_qualifier's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param assessment method that will be called with the value of the outgoing data
   *        port 'assessment'.
   */
  def check_concrete_output(assessment: Factory_Dispatch_Coordinator.Dock_Assessment.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val assessmentValue: Factory_Dispatch_Coordinator.Dock_Assessment.Type = get_assessment().get
    if(!assessment(assessmentValue)) {
      testFailures = testFailures :+ st"'assessment' did not match expected: value of the outgoing data port is ${assessmentValue}"
